// Anton glyph outlines (generated by scripts/build-glyphs.mjs) laid out into
// SVG path data, so display type can be stroke-traced like a pen plotter.
import data from '@/data/glyphs.json';

type GlyphData = { d: string; w: number };
const GLYPHS = data.glyphs as Record<string, GlyphData>;

export const GLYPH_EM = data.size;
export const CAP_HEIGHT = data.capHeight;

export interface LaidGlyph {
  ch: string;
  d: string;
  /** Left edge of the glyph's advance box. */
  x: number;
  w: number;
}

/** Lays out uppercase `text` left to right. Unknown characters render as spaces. */
export function layoutGlyphs(text: string, tracking = -1): { glyphs: LaidGlyph[]; width: number } {
  const glyphs: LaidGlyph[] = [];
  let x = 0;
  for (const raw of text.toUpperCase()) {
    const g = GLYPHS[raw] ?? GLYPHS[' '];
    if (raw !== ' ' && g.d) glyphs.push({ ch: raw, d: g.d, x, w: g.w });
    x += g.w + tracking;
  }
  return { glyphs, width: Math.max(1, x - tracking) };
}
